import subprocess
from pathlib import Path

repo=Path("/Users/steventran/do-again")
wt=Path("/Users/steventran/.do_again/lifecycle-ci-20261007")
branch="feat/ci-wait-lifecycle-20261007"
expected="cbf5f56a41d3a61a33b4b3ea873d93461d4fc232"

def run(args,cwd=repo,check=True):
    return subprocess.run(args,cwd=cwd,text=True,capture_output=True,check=check)

# Preserve original checkout; only require tracked cleanliness.
status=run(["git","status","--porcelain=v1"]).stdout.splitlines()
tracked=[x for x in status if not x.startswith("?? ")]
if tracked:
    raise SystemExit(f"tracked changes in source checkout: {tracked}")

fetch=run(["git","fetch","origin","main"],check=False)
print(fetch.stdout); print(fetch.stderr)
if fetch.returncode: raise SystemExit(fetch.returncode)
origin=run(["git","rev-parse","origin/main"]).stdout.strip()
print("origin_main="+origin)
if origin!=expected:
    raise SystemExit(f"unexpected origin/main {origin}")

if wt.exists():
    raise SystemExit(f"worktree exists: {wt}")
if run(["git","show-ref","--verify",f"refs/heads/{branch}"],check=False).returncode==0:
    raise SystemExit(f"branch exists: {branch}")

add=run(["git","worktree","add","-b",branch,str(wt),expected],check=False)
print(add.stdout); print(add.stderr)
if add.returncode: raise SystemExit(add.returncode)

def wrun(args):
    return run(args,cwd=wt)
print("branch="+wrun(["git","branch","--show-current"]).stdout.strip())
print("head="+wrun(["git","rev-parse","HEAD"]).stdout.strip())
print("status="+repr(wrun(["git","status","--porcelain=v1"]).stdout))

for rel in ["src/do_again/service/liveness.py","tests/test_liveness.py","src/do_again/cli.py"]:
    p=wt/rel
    print(f"\n===== {rel} =====")
    lines=p.read_text().splitlines()
    for i,l in enumerate(lines):
        if any(k in l.lower() for k in ("goal_state","waiting_for_ci","continuous","progress_at","recover","stalled","check_liveness","github","workflow")):
            a=max(0,i-4); b=min(len(lines),i+10)
            print(f"--- {a+1}-{b} ---")
            for j in range(a,b): print(f"{j+1}: {lines[j]}")
